function naughtyHref(name, href) {
    href = href.replace(/[\x00-\x20]+/g, '');
    href = href.replace(/<!--.*?-->/g, '');
    const matches = href.match(/^([a-zA-Z][a-zA-Z0-9.\-+]*):/);
    if (!matches) {
      if (href.match(/^[/\\]{2}/)) {
        return !options.allowProtocolRelative;
      }

      return false;
    }
    const scheme = matches[1].toLowerCase();

    if (has(options.allowedSchemesByTag, name)) {
      return options.allowedSchemesByTag[name].indexOf(scheme) === -1;
    }

    return !options.allowedSchemes || options.allowedSchemes.indexOf(scheme) === -1;
  }

function getCsrfToken() {
    if (csrf) return csrf

    if (document.querySelector('[data-csrf]')) {
        csrf = document.querySelector('[data-csrf]').getAttribute('data-csrf')

        return csrf
    }

    if (window.livewireScriptConfig['csrf'] ?? false) {
        csrf = window.livewireScriptConfig['csrf']

        return csrf
    }

    throw 'Livewire: No CSRF token detected'
}

function _makeSetter(property, next) {
	if (
		property === '__proto__' ||
		property === 'constructor' ||
		property === 'prototype'
	) {
		throw new Error('unable to access __proto__, constructor, prototype');
	}

	if (next) {
		return function setter(ctx, value) {
			var t = ctx[property];

			if (!t) {
				t = ctx[property] = {};
			}

			return next(t, value);
		};
	} else {
		return function (ctx, value) {
			ctx[property] = value;
			return ctx;
		};
	}
}

